const VEGETATION_ART={tree1:{path:'tree_snow_01.png',sw:96,sh:128,cx:48,foot:125,scale:1,rx:12,ry:8},tree2:{path:'tree_snow_02.png',sw:96,sh:128,cx:48,foot:124,scale:1,rx:12,ry:8},bush1:{path:'bush_snow_01.png',sw:64,sh:64,cx:32,foot:58,scale:.75,rx:20,ry:8},bush2:{path:'bush_snow_02.png',sw:96,sh:96,cx:48,foot:82,scale:.75,rx:28,ry:9},bush3:{path:'bush_snow_03.png',sw:96,sh:64,cx:48,foot:59,scale:.75,rx:32,ry:8}};
