const SHELVES=[{group:'balls',name:'B\xe4lle',x:160,y:340},{group:'kits',name:'Trikots',x:265,y:340},{group:'training',name:'Training',x:370,y:340}];
// Hand-placed mixed edge groups; paths and activity areas stay open.
const ENV_CLUSTERS=[
 {zone:'base',x:150,y:620,plants:[['tree1',-60,30],['tree2',70,35],['bush1',-55,-20],['bush2',120,20]],snow:[['big',-10,-10],['mid',25,5],['small',55,-3]]},
 {zone:'base',x:840,y:620,plants:[['tree1',-50,30],['tree2',60,30],['bush3',-5,15],['bush1',-85,25]],snow:[['big',40,-10],['mid',15,5],['small',70,0]]},
 {zone:'training',x:160,y:205,plants:[['tree1',-80,-15],['tree2',50,0],['bush2',-15,35],['bush1',90,35]],snow:[['big',10,-10],['mid',40,15],['small',-50,20]]},
 {zone:'training',x:825,y:625,plants:[['tree1',65,25],['tree2',-65,25],['bush3',-5,20],['bush1',-95,-15]],snow:[['big',45,-20],['mid',10,-10],['small',80,0]]},
 {zone:'stadium',x:135,y:615,plants:[['tree1',-60,25],['tree2',55,35],['bush2',0,30],['bush1',60,-10]],snow:[['big',-20,-30],['mid',15,-15],['small',-35,0]]},
 {zone:'stadium',x:840,y:190,plants:[['tree1',65,-25],['tree2',-60,-25],['bush3',10,30],['bush1',-100,20]],snow:[['big',10,-20],['mid',45,5],['small',-25,5]]}
];
const VEGETATION=ENV_CLUSTERS.flatMap(c=>c.plants.map(([k,dx,dy])=>({zone:c.zone,k,x:c.x+dx,y:c.y+dy})));
const SNOW=ENV_CLUSTERS.flatMap(c=>c.snow.map(([k,dx,dy])=>({zone:c.zone,k:'snow_'+k,x:c.x+dx,y:c.y+dy})));
function vegetationLayout(v){const m=VEGETATION_ART[v.k];return{x:v.x-m.cx*m.scale,y:v.y-m.foot*m.scale,w:m.sw*m.scale,h:m.sh*m.scale};}
function drawVegetation(v){const b=vegetationLayout(v);ctx.drawImage(imgs[v.k],b.x,b.y,b.w,b.h);}
function vegetationBlocked(x,y,zone){return VEGETATION.some(v=>{if(v.zone!==zone)return false;const m=VEGETATION_ART[v.k];return((x-v.x)/m.rx)**2+((y-(v.y-3))/m.ry)**2<1;});}
const fresh=()=>({boardsRemoved:false,windowCleaned:false,windowNails:[],entrances:{material:false,meeting:false},entranceCleared:false,shovel:false,items:[],container:false,lights:false,garage:false,heating:false,sorted:[],carrying:null,layoutVersion:2,zone:'base',visited:['base'],explored:{base:[],training:[],stadium:[],container:[]},trash:[],x:home.x,y:home.y,room:false,direction:'front'});
let state=fresh(),storage=true,ready=false,last=0,view={w:0,h:0,scale:2,x:0,y:0},walk=0,toastTimer,returnDoor=doorLeft,lastRevealKey='';
function doorCleared(room){return state.entrances?.[room]===true||state.entranceCleared===true;}
const SNOW_BOUNDS={snow_small:{top:20,left:15,right:48,bottom:44},snow_mid:{top:14,left:8,right:55,bottom:47},snow_big:{top:9,left:2,right:61,bottom:54}};
function visibleSnow(zone=state.zone){const piles=SNOW.filter(p=>p.zone===zone);if(zone==='base')for(const [room,d] of [['material',doorLeft],['meeting',doorRight]])if(!doorCleared(room))piles.push({k:'snow_small',x:d.x-25,y:310},{k:'snow_big',x:d.x,y:320},{k:'snow_mid',x:d.x+26,y:316});return piles;}
function snowShape(p){const sz=PROP_SIZE[p.k],b=SNOW_BOUNDS[p.k],scale=sz.w/64;return{x:p.x,y:p.y-3,rx:(b.right-b.left+1)*scale*.43+5,ry:Math.max(7,sz.h*.12)};}
function snowBlocked(x,y,zone){return visibleSnow(zone).some(p=>{const b=snowShape(p);return((x-b.x)/b.rx)**2+((y-b.y)/b.ry)**2<1;});}
function outdoorBlocked(x,y,zone=state.zone){return x<32||y<72||x>W-32||y>H-32||snowBlocked(x,y,zone)||vegetationBlocked(x,y,zone)||(zone==='base'&&exterior.some(r=>x>r.x-6&&x<r.x+r.w+6&&y>r.y-6&&y<r.y+r.h+6));}

try{const raw=localStorage.getItem(KEY);const v=raw?JSON.parse(raw):null;if(v&&typeof v==='object'){
 const unique=(a,max)=>Array.isArray(a)?[...new Set(a.filter(n=>Number.isInteger(n)&&n>=0&&n<max))]:[];
 const items=unique(v.items,6),sorted=unique(v.sorted,6);state={...fresh(),boardsRemoved:v.boardsRemoved===true||v.container===true,windowCleaned:v.windowCleaned===true||v.container===true,windowNails:unique(v.windowNails,4),entrances:{material:v.entrances?.material===true||v.entranceCleared===true||v.container===true,meeting:v.entrances?.meeting===true||v.entranceCleared===true||v.container===true},entranceCleared:v.entranceCleared===true||v.container===true,shovel:v.shovel===true,items,sorted,carrying:Number.isInteger(v.carrying)&&v.carrying>=0&&v.carrying<6&&!sorted.includes(v.carrying)?v.carrying:null,container:v.container===true&&items.length===6,lights:v.lights===true&&v.container===true&&items.length===6,garage:v.garage===true&&v.container===true,heating:v.heating===true&&v.garage===true&&v.container===true,trash:unique(v.trash,TRASH.length)};
 if(v.layoutVersion===2){state.zone=ZONES[v.zone]?v.zone:'base';state.visited=[...new Set(['base',state.zone,...(Array.isArray(v.visited)?v.visited.filter(z=>ZONES[z]):[])])];for(const z of Object.keys(state.explored))state.explored[z]=unique(v.explored?.[z],165);if(Number.isFinite(v.x)&&Number.isFinite(v.y)&&!outdoorBlocked(v.x,v.y,state.zone)){state.x=v.x;state.y=v.y;}}
}}catch{storage=false;}
const coins=()=>state.items.length*10+(state.garage?40:0)-(state.container?40:0)-(state.lights?20:0)-(state.heating?40:0)+(state.sorted.length===SORT_ITEMS.length?20:0)+state.trash.length*5;

function save(){try{localStorage.setItem(KEY,JSON.stringify(state.room?{...state,room:false,zone:'base',x:returnDoor.x,y:returnDoor.y+20}:state));}catch{storage=false;}hud();}
function hud(){const left=objects.filter((o,i)=>o.zone===state.zone&&!state.items.includes(i)).length;let task=state.items.length<6?[`Material finden \xb7 ${state.items.length}/6`,left?`${ZONES[state.zone].name}: noch ${left} Fundst\xfccke. Nah herangehen und gedr\xfcckt halten.`:state.zone==='base'?'Hier ist alles gefunden. Weg rechts: Training. Weg unten: Spieltag.':'Hier ist alles gefunden. Folge dem Weg zur\xfcck zum Containerhof.']:!state.windowCleaned?['Fenster herrichten',state.boardsRemoved?'Das Fenster mit dem Lappen reinigen.':'Am Containerfenster zuerst die N\xe4gel ziehen.']:!state.entranceCleared?['Eing\xe4nge freischaufeln','Jede Containert\xfcr einzeln freir\xe4umen. Schaufel im Hof aufnehmen.']:!state.container?['J\xf6rg anrufen','Am Ausbau-Schild hilft J\xf6rg Rodewald beim Herrichten. Material: 40 Taler.']:!state.lights?['Lichter anbringen','Am Ausbau-Schild im Containerhof \xb7 20 Taler.']:!state.garage?['Pfand einlagern','Im linken Containerraum \xb7 +40 Taler.']:!state.heating?['Rasenheizung kaufen','Im Bereich Spieltag am Schild neben dem Platz \xb7 40 Taler.']:['Der Hauptplatz ist aufgetaut!','Verkaufsstand, Trib\xfcne und Flutlicht folgen als n\xe4chste Ausbauten.'];if(state.room&&state.container&&state.sorted.length<SORT_ITEMS.length)task=[`Material sortieren \xb7 ${state.sorted.length}/6`,state.carrying===null?'Gegenstand aufnehmen und zu den Regalen oben bringen.':`${SORT_ITEMS[state.carrying].name} in der Hand. Geh zum passenden Regal und halte es gedr\xfcckt.`];if(state.room==='meeting'&&state.carrying===null)task=['Mannschaftstreffpunkt','Sammelheft auf dem Tisch ansehen. Der Materialraum ist links.'];$('stats').textContent=`${coins()} Taler \xb7 Level ${1+Number(state.container)+Number(state.lights)+Number(state.heating)}`;$('task').textContent=task[0];$('detail').textContent=task[1];$('area-name').textContent=state.room?'Container':ZONES[state.zone].name;$('storage').textContent=storage?'Automatisch gespeichert: Fortschritt und erkundete Kartenbereiche, lokal in diesem Browser.':'Speichern ist hier nicht verf\xfcgbar. Fortschritt kann beim Schlie\xdfen verloren gehen.';}

function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function resize(){const dpr=Math.min(devicePixelRatio||1,2);view.w=innerWidth;view.h=innerHeight;canvas.width=Math.round(view.w*dpr);canvas.height=Math.round(view.h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;view.scale=(view.h<430?1.5:2)*1.10;}
function blocked(x,y){if(!state.room)return outdoorBlocked(x,y);return x<105||x>790||y<155||y>570||(x>426&&x<454&&!(y>310&&y<410))||(x>130&&x<395&&y<315)||(x>510&&x<755&&y<270)||(x>560&&x<690&&y>345&&y<425);}
function actions(){if(state.room)return[{id:'exit',type:'exit',room:state.room,x:state.room==='material'?250:650,y:570,label:'Nach drau\xdfen',duration:550},{id:'other-exit',type:'exit',room:state.room==='material'?'meeting':'material',x:state.room==='material'?650:250,y:570,label:'Nach drau\xdfen',duration:550},...sortActions(),{id:'garage',type:'garage',x:120,y:560,label:state.garage?'Pfand eingelagert':'Pfand einlagern \xb7 +40 Taler',duration:1700},{id:'album',type:'album',x:620,y:400,label:'Sammelheft durchbl\xe4ttern',duration:550},{id:'souvenir',type:'souvenir',x:775,y:300,label:'Das Fundst\xfcck ansehen',duration:450}];const items=objects.flatMap((o,i)=>o.zone!==state.zone||state.items.includes(i)?[]:[{...o,id:'item'+i,type:'item',i,label:o.name+' verstauen',duration:850}]);const trash=TRASH.flatMap((o,i)=>o.zone!==state.zone||state.trash.includes(i)?[]:[{...o,id:'trash'+i,type:'trash',i,label:'M\xfcllbeutel entsorgen',duration:650}]);const extras=state.zone==='base'?[...(!state.windowCleaned?[{id:'repair-window',type:'repair',x:670,y:315,label:state.boardsRemoved?'Fenster reinigen':'Fensterbretter entfernen',duration:500}]:[]),{id:'left',type:'enter',room:'material',...doorLeft,label:doorCleared('material')?'Materialraum betreten':'Eingang freischaufeln',duration:500},{id:'right',type:'enter',room:'meeting',...doorRight,label:doorCleared('meeting')?'Treffpunkt betreten':'Eingang freischaufeln',duration:500},{id:'upgrade',type:'upgrade',...upgrade,label:!state.container?'J\xf6rg anrufen \xb7 40 Taler Material':!state.lights?'Lichter \xb7 20 Taler':'Container fertig',duration:1400},{id:'shovel',type:'shovel',x:165,y:370,label:state.shovel?'Schaufel ablegen':'Schaufel aufnehmen',duration:500}]:state.zone==='stadium'?[{id:'heat',type:'heat',...heater,label:state.heating?'Rasenheizung l\xe4uft':'Rasenheizung \xb7 40 Taler',duration:1600}]:[];return[...items,...trash,...extras,...GATES[state.zone]];}

function sortActions(){if(!state.room||!state.container||state.sorted.length===SORT_ITEMS.length)return[];if(state.carrying===null)return SORT_ITEMS.flatMap((o,i)=>state.sorted.includes(i)?[]:[{...o,id:'sort-pick-'+i,type:'sort-pick',i,label:o.name+' aufnehmen',duration:450}]);return SHELVES.map(o=>({...o,id:'sort-put-'+o.group,type:'sort-put',label:o.name+' einsortieren',duration:550}));}
const distance=a=>Math.hypot(state.x-a.x,state.y-a.y);
function actionTarget(){return actions().filter(a=>distance(a)<76).sort((a,b)=>distance(a)-distance(b))[0]||null;}
function perform(a){if(!ready||$('settings').open||$('album').open||$('repair').open||!a||distance(a)>=76)return false;if(a.type==='repair'){openRepair('nails');return true;}else if(a.type==='shovel'){state.shovel=!state.shovel;if(!state.shovel)toast('Schaufel wieder am Ger\xe4teraum abgelegt.');else toast('Schaufel ausger\xfcstet. Geh zum Eingang des Containers und r\xe4ume den Schnee weg.');}else if(a.type==='travel'){travel(a);return true;}else if(a.type==='album'){openAlbum();return true;}else if(a.type==='souvenir'){toast('Der legend\xe4re Fund. Manche Dinge werden einfach Vereinsgeschichte.');return true;}else if(a.type==='trash'){if(state.trash.includes(a.i))return false;state.trash.push(a.i);toast('M\xfcllbeutel entsorgt. +5 Vereinstaler.');}else if(a.type==='sort-pick'){if(state.carrying!==null||state.sorted.includes(a.i)||!SORT_ITEMS[a.i])return false;state.carrying=a.i;toast(SORT_ITEMS[a.i].name+' aufgenommen. Bring es zum passenden Regal.');}else if(a.type==='sort-put'){if(state.carrying===null)return false;const item=SORT_ITEMS[state.carrying];if(item.group!==a.group){toast('Das geh\xf6rt ins Regal '+SHELVES.find(r=>r.group===item.group).name+'.');return false;}if(state.sorted.includes(state.carrying))return false;state.sorted.push(state.carrying);state.carrying=null;toast(state.sorted.length===SORT_ITEMS.length?'Alles einsortiert! +20 Vereinstaler.':'Richtig einsortiert!');}else if(a.type==='item'){if(state.items.includes(a.i))return false;state.items.push(a.i);toast(`${objects[a.i].name} verstaut. +10 Vereinstaler`);}else if(a.type==='enter'){if(!doorCleared(a.room)){openRepair('snow',a.room);return true;}returnDoor=a.room==='material'?doorLeft:doorRight;state.room=a.room;state.x=a.room==='material'?250:650;state.y=520;toast(a.room==='material'?'Material und Pfandlager \xb7 links':'Mannschaftstreffpunkt \xb7 rechts');}else if(a.type==='exit'){if(!doorCleared(a.room)){openRepair('snow',a.room);return true;}returnDoor=a.room==='material'?doorLeft:doorRight;state.room=false;state.zone='base';state.x=returnDoor.x;state.y=returnDoor.y+20;}else if(a.type==='upgrade'){if(!state.container){if(!state.windowCleaned||!doorCleared('material')||!doorCleared('meeting')){toast('Reinige zuerst das Fenster und r\xe4ume beide Eing\xe4nge frei.');return false;}if(state.items.length<6||coins()<40){toast('Sammle zuerst die sechs Gegenst\xe4nde ein.');return false;}state.container=true;toast('J\xf6rg Rodewald packt mit an. Mit eurem Material wird der Container wieder fit!');}else if(!state.lights){if(coins()<20)return false;state.lights=true;toast('Licht an f\xfcr die Winterabende.');}else{toast('Der Container ist bereits fertig.');return false;}}else if(a.type==='garage'){if(!state.container){toast('Richte zuerst den Container her.');return false;}if(state.garage){toast('Das Pfand ist bereits eingelagert.');return false;}state.garage=true;toast('Pfand eingelagert. +40 Vereinstaler!');}else if(a.type==='heat'){if(state.heating){toast('Die Rasenheizung l\xe4uft bereits.');return false;}if(!state.container||!state.garage||coins()<40){toast('Lagere zuerst das Pfand im linken Containerraum ein: +40 Taler.');return false;}state.heating=true;toast('Rasenheizung an! Der Hauptplatz taut auf.');}cancelHold();reveal(true);save();return true;}
function interact(){perform(actionTarget());}
function fill(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
function text(x,y,t,size=12,c='#fff1cb'){ctx.font=`400 ${size}px ${size>=17?'RasterForge':'Minecraftia'}, Nunito, sans-serif`;ctx.fillStyle=c;ctx.textBaseline='alphabetic';const ascent=ctx.measureText(t)?.actualBoundingBoxAscent??size;ctx.fillText(t,x,y+ascent);}
function spriteLayout(k,x,y,w=32,h=32){let foot=1;if(k.includes('_shovel_')){const scale=.525,d=k.split('_')[0],phase=k.endsWith('_w')?'w':'s';return{x:x-32*scale,y:y-PLAYER_FOOT[d+'_'+phase]*scale,w:(k==='back_shovel_s'?68:64)*scale,h:96*scale};}if(PLAYER_FOOT[k]!==undefined){w=32*1.05;h=48*1.05;foot=PLAYER_FOOT[k]/96;}else if(PROP_SIZE[k]){const p=PROP_SIZE[k];w=p.w;h=p.h;foot=p.foot/(p.sourceH||32);}return{x:x-w/2,y:y-h*foot,w,h};}
