function camera(){const ww=state.room?880:W,hh=state.room?700:H;view.x=ww<view.w/view.scale?(ww-view.w/view.scale)/2:Math.max(0,Math.min(ww-view.w/view.scale,state.x-view.w/view.scale/2));view.y=hh<view.h/view.scale?(hh-view.h/view.scale)/2:Math.max(0,Math.min(hh-view.h/view.scale,state.y-view.h/view.scale*.60));if(state.room){view.x=state.x-view.w/view.scale/2;view.y=state.y-view.h/view.scale*.60;}view.x=Math.round(view.x*view.scale)/view.scale;view.y=Math.round(view.y*view.scale)/view.scale;}
function project(x,y){return{x:(x-view.x)*view.scale,y:(y-view.y)*view.scale};}
const FLAKES=[{k:'flake1',x:6,y:5,w:5,h:5,size:6},{k:'flake2',x:3,y:3,w:9,h:9,size:8},{k:'flake3',x:3,y:3,w:9,h:11,size:8},{k:'flake4',x:3,y:3,w:2,h:2,size:3},{k:'flake5',x:2,y:2,w:4,h:4,size:5}];
