function resetSnowfall(){SNOW_PARTICLES.length=0;for(let i=0;i<90;i++){const flake=i%FLAKES.length;SNOW_PARTICLES.push({x:Math.random()*view.w,y:Math.random()*view.h,speed:16+Math.random()*35,drift:(Math.random()-.5)*25,amp:3+Math.random()*12,phase:Math.random()*Math.PI*2,freq:.45+Math.random()*1.1,coupling:.3+Math.random()*.9,flake,size:Math.round(FLAKES[flake].size*(.8+Math.random()*.55)),alpha:.55+Math.random()*.4});}lastSnowTime=null;snowViewport=view.w+'x'+view.h;}
function drawSnowfall(time){if(snowViewport!==view.w+'x'+view.h||SNOW_PARTICLES.length!==90)resetSnowfall();const dt=lastSnowTime===null?0:Math.max(0,Math.min((time-lastSnowTime)/1000,.06));lastSnowTime=time;const wind=Math.sin(time*.00013)*5+Math.sin(time*.00041)*2;for(const p of SNOW_PARTICLES){p.x+=(p.drift+wind*p.coupling)*dt;p.y+=p.speed*dt;if(p.y>view.h+18){p.y=-18-Math.random()*20;p.x=Math.random()*view.w;p.phase=Math.random()*Math.PI*2;}if(p.x>view.w+30)p.x=-30;else if(p.x<-30)p.x=view.w+30;const f=FLAKES[p.flake],x=Math.round(p.x+Math.sin(time*.001*p.freq+p.phase)*p.amp),y=Math.round(p.y);ctx.globalAlpha=p.alpha;ctx.drawImage(imgs[f.k],f.x,f.y,f.w,f.h,x,y,p.size,p.size);}ctx.globalAlpha=1;}

