function cancelHold(){hold.id=null;hold.action=null;hold.progress=0;$('interact').style.setProperty('--progress','0%');}
function updateHold(time){if(!hold.action)return;const a=actions().find(a=>a.id===hold.action.id);if(!a||distance(a)>=76||Math.hypot(stick.x,stick.y)>.1||keys.size||$('settings').open){cancelHold();return;}hold.progress=Math.min(1,(time-hold.start)/a.duration);$('interact').style.setProperty('--progress',hold.progress*100+'%');if(hold.progress>=1){cancelHold();perform(a);}}
function canPlay(){return ready&&!$('settings').open&&!$('album').open&&!$('repair').open&&!document.hidden&&!(matchMedia('(orientation: portrait) and (max-width: 700px)').matches&&!$('rotate').classList.contains('dismissed'));}
let previousLabel='';function frame(time){if(!ready)return;const dt=Math.min((time-last)/1000,.04)||0;last=time;if(canPlay()){let dx=Number(keys.has('d')||keys.has('ArrowRight'))-Number(keys.has('a')||keys.has('ArrowLeft'))+stick.x,dy=Number(keys.has('s')||keys.has('ArrowDown'))-Number(keys.has('w')||keys.has('ArrowUp'))+stick.y;const len=Math.hypot(dx,dy);if(len>.08){dx/=Math.max(1,len);dy/=Math.max(1,len);let moved=false;const nx=state.x+dx*140*dt,ny=state.y+dy*140*dt;if(!blocked(nx,state.y)){state.x=nx;moved=true;}if(!blocked(state.x,ny)){state.y=ny;moved=true;}state.direction=Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'front':'back';walk=moved?walk+dt*8:0;}else walk=0;checkTransition();reveal();updateHold(time);const target=actionTarget(),label=target?.label||'Geh n\xe4her heran';if(label!==previousLabel){$('interact').querySelector('span').textContent=label;previousLabel=label;}$('interact').disabled=!target;}else cancelHold();updateRepairShake(time);render(time);requestAnimationFrame(frame);}
