function stickMove(e){if(e.pointerId!==stick.id)return;const dx=e.clientX-stick.cx,dy=e.clientY-stick.cy,len=Math.hypot(dx,dy),max=34;stick.x=dx/Math.max(max,len);stick.y=dy/Math.max(max,len);$('knob').style.transform=`translate(${stick.x*max}px,${stick.y*max}px)`;}
function hitAction(e){const wx=e.clientX/view.scale+view.x,wy=e.clientY/view.scale+view.y;return actions().filter(a=>distance(a)<76&&Math.abs(wx-a.x)<32&&wy>a.y-65&&wy<a.y+20).sort((a,b)=>Math.hypot(wx-a.x,wy-a.y)-Math.hypot(wx-b.x,wy-b.y))[0];}
