function reveal(force=false){const z=state.room?'container':state.zone,cx=Math.floor(state.x/64),cy=Math.floor(state.y/64),key=z+':'+cx+':'+cy;if(!force&&lastRevealKey===key&&state.explored[z].length)return;lastRevealKey=key;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const x=cx+dx,y=cy+dy;if(dx*dx+dy*dy<=5&&x>=0&&x<15&&y>=0&&y<11){const n=y*15+x;if(!state.explored[z].includes(n))state.explored[z].push(n);}}if(!state.room&&!state.visited.includes(state.zone))state.visited.push(state.zone);}
